import sys
from math import sqrt

def is_prime(x):
    if x < 2:
        return False
    if x == 2:
        return True
    if x % 2 == 0:
        return False
    limit = int(sqrt(x)) + 1
    for i in range(3, limit, 2):
        if x % i == 0:
            return False
    return True

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        n = int(next(iterator))
        k = int(next(iterator))
    except StopIteration:
        return

    cards = []
    for _ in range(n):
        p = int(next(iterator))
        c = int(next(iterator))
        l = int(next(iterator))
        cards.append((p, c, l))

    levels = sorted(set(l for _, _, l in cards))

    for level in levels:
        available = [i for i, (_, _, l) in enumerate(cards) if l <= level]

        if not available:
            continue

        m = len(available)
        adj = [[False] * m for _ in range(m)]
        powers = []
        magic_nums = []

        for idx, orig_idx in enumerate(available):
            p, c, _ = cards[orig_idx]
            powers.append(p)
            magic_nums.append(c)

        for i in range(m):
            for j in range(i + 1, m):
                if is_prime(magic_nums[i] + magic_nums[j]):
                    adj[i][j] = adj[j][i] = True

        dp = [-1] * (m + 1)
        dp[0] = 0

        for i in range(m):
            new_dp = dp[:]
            for j in range(i + 1):
                if dp[j] != -1:
                    can_add = True
                    for t in range(j):
                        if t < i and adj[i][t]:
                            can_add = False
                            break
                    if can_add:
                        if new_dp[j + 1] < dp[j] + powers[i]:
                            new_dp[j + 1] = dp[j] + powers[i]
            dp = new_dp

        max_power = max(dp)
        if max_power >= k:
            print(level)
            return

    print(-1)

solve()
